<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">ASSET</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                 READINGS
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <div class="row layout-top-spacing">
        <div class="d-flex">
            <div class="ms-auto">
                <button class="btn btn-primary m-2"
                data-bs-toggle="modal" data-bs-target="#register">
                <i class="bi bi-plus-square"></i>
                </button>
            </div>
        </div>
      <div v-if="loading" v-html="tableShimmer()"></div>
      <div 
      v-else
      class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div class="panel p-0">
          <div class="custom-table table3">
            <v-client-table :data="readings" :columns="columns" :options="table_option">
            </v-client-table>
          </div>
        </div>
      </div>
    </div>
    </div>

    <!-- manual registration modla starts -->
     
                 <div class="modal fade mymodal" id="register" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">ASSET READING</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" ></button>
      </div>
<div class="modal-body" >
      <div class="row layout-top-spacing" style="max-height: 67vh; overflow-y: auto;">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                      <div class="row">
                        <div class="col-md-4">
                          <label class="form-label">Initial Reading </label>
                          <input  class="form-control" type="number" step="any" placeholder="Enter Initial Reading">
                        </div>

                           <div class="col-md-4">
                          <label class="form-label">Final Reading </label>
                          <input class="form-control" type="number" step="any" placeholder="Enter Final Reading">
                        </div>


                      </div>
                    </div>
                </div>
            </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>

      </div>

    </div>
  </div>

</div>
     <!-- manual registration modal ends -->


</template>

<script setup>
import { ref, onMounted ,watch, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
})

const loading = ref(false)
const formatDate = inject('formatDate')
const columns = ref(['Sno','asset', 'reading', 'source','read_by','time','location','actions']);
const readings = ref([])
const tableShimmer = inject('tableShimmer')
const getReadings = async () => {
    loading.value = true
    try{
const res = await axiosInstance.get('/readings')
  readings.value = res.data.map((item,index)=>({
    ...item,
   Sno : index + 1,
   asset :item?.subject?.asset?.name + ' - ' +item?.subject?.asset?.type_name ,
   reading : item?.reading_value,
   source : item?.reading_source,
   read_by : item?.handler,
   time : formatDate(item?.reading_time),
   location :item?.location?.name
  }))
    }finally{
     loading.value = false
    }
  
}




onMounted(() => {
  getReadings()
})
</script>